<script setup lang="ts">
import { ref } from 'vue';
import { Link, router } from '@inertiajs/vue3';
import AppLayout from '../../Layouts/AppLayout.vue';
import { Activity, ChartNoAxesCombined, ChevronLeft, Ruler, Search, UsersRound } from '@lucide/vue';
type Team = { id: number; name: string };
type Assessment = { date: string; height_cm: number | null; weight_kg: number | null; vertical_jump_cm: number | null; spike_reach_cm: number | null; block_reach_cm: number | null; recorder: string | null };
type Athlete = { id: number; name: string; membership_number: string; team: string | null; position: string | null; number: number | null; last_assessment: Assessment | null; needs_assessment: boolean };
type Paginated = { data: Athlete[]; links: { url: string | null; label: string; active: boolean }[]; total: number; from: number; to: number };
const props = defineProps<{ athletes: Paginated; teams: Team[]; filters: { search?: string; team?: string }; summary: { total: number; assessed: number; outdated: number } }>();
const search = ref(props.filters.search || ''); const teamFilter = ref(props.filters.team || '');
const applyFilters = () => router.get('/assessments', { search: search.value || undefined, team: teamFilter.value || undefined }, { preserveState: true, replace: true });
const dateLabel = (value: string) => new Intl.DateTimeFormat('fa-IR', { day: 'numeric', month: 'short', year: 'numeric' }).format(new Date(`${value}T12:00:00`));
const paginationLabel = (label: string) => label.replace('&laquo; Previous', 'قبلی').replace('Next &raquo;', 'بعدی');
</script>
<template><AppLayout title="ارزیابی عملکرد ورزشی" eyebrow="رکوردگیری تخصصی والیبال" active="manager">
<section class="mb-5 grid gap-4 sm:grid-cols-3"><article class="access-stat"><div><span>ورزشکاران در دسترس</span><strong>{{ summary.total }}</strong></div><UsersRound :size="22" /></article><article class="access-stat"><div><span>دارای ارزیابی</span><strong>{{ summary.assessed }}</strong></div><ChartNoAxesCombined :size="22" /></article><article class="access-stat"><div><span>نیازمند ارزیابی جدید</span><strong>{{ summary.outdated }}</strong></div><Activity :size="22" /></article></section>
<section class="panel-flat"><header class="users-toolbar"><form class="flex flex-1 flex-col gap-2 md:flex-row" @submit.prevent="applyFilters"><div class="relative min-w-0 flex-1"><Search class="absolute right-3 top-1/2 -translate-y-1/2 text-[#8a959b]" :size="16" /><input v-model="search" class="table-filter pr-9" placeholder="نام یا کد عضویت ورزشکار"></div><select v-model="teamFilter" class="table-filter md:max-w-52" @change="applyFilters"><option value="">همه تیم‌ها</option><option v-for="team in teams" :key="team.id" :value="team.id">{{ team.name }}</option></select><button class="secondary-button justify-center">جست‌وجو</button></form></header>
<div class="overflow-x-auto"><table class="sport-table assessment-table"><thead><tr><th>ورزشکار</th><th>آخرین ارزیابی</th><th>قد / وزن</th><th>پرش عمودی</th><th>دسترسی اسپک</th><th>وضعیت</th><th /></tr></thead><tbody><tr v-for="athlete in athletes.data" :key="athlete.id"><td><div class="flex items-center gap-3"><div class="jersey-no">{{ athlete.number || '—' }}</div><div><strong class="block">{{ athlete.name }}</strong><span class="mt-1 block text-[8px] text-[#879198]">{{ athlete.team }} · {{ athlete.position }}</span></div></div></td><td>{{ athlete.last_assessment ? dateLabel(athlete.last_assessment.date) : 'بدون ارزیابی' }}</td><td><span v-if="athlete.last_assessment">{{ athlete.last_assessment.height_cm }} cm · {{ athlete.last_assessment.weight_kg }} kg</span><span v-else>—</span></td><td><strong>{{ athlete.last_assessment?.vertical_jump_cm ?? '—' }}</strong><small v-if="athlete.last_assessment"> cm</small></td><td><strong>{{ athlete.last_assessment?.spike_reach_cm ?? '—' }}</strong><small v-if="athlete.last_assessment"> cm</small></td><td><span :class="athlete.needs_assessment ? 'tag-warn' : 'tag-ok'">{{ athlete.needs_assessment ? 'نیازمند ثبت' : 'به‌روز' }}</span></td><td><Link :href="`/assessments/${athlete.id}`" class="row-action" title="مشاهده و ثبت"><ChevronLeft :size="17" /></Link></td></tr></tbody></table></div>
<footer class="flex flex-col gap-3 border-t border-[#e2e5e6] px-5 py-4 sm:flex-row sm:items-center sm:justify-between"><p class="text-[9px] text-[#7d8990]">نمایش {{ athletes.from || 0 }} تا {{ athletes.to || 0 }} از {{ athletes.total }} ورزشکار</p><div class="flex gap-1"><Link v-for="link in athletes.links" :key="link.label" :href="link.url || '#'" class="pagination-link" :class="{ 'pagination-active': link.active, 'pointer-events-none opacity-40': !link.url }" v-html="paginationLabel(link.label)" /></div></footer></section>
</AppLayout></template>
